import assert from 'node:assert/strict';
const command=async(path,input)=>{const response=await fetch('http://127.0.0.1:5484/'+path,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(input)});assert.equal(response.ok,true,await response.clone().text());return response.json();};
const run=code=>command('eval',{code});
const until=async(code)=>{for(let i=0;i<100;i++){if(await run(code))return;await new Promise(resolve=>setTimeout(resolve,50));}throw Error('Timed out: '+code);};
const capture=name=>command('capture',{name:'rework-'+name});
await run('location.hash="/mail";location.reload()');
await until('document.querySelectorAll(".mail-message-row").length===25');
await run('Array.from(document.querySelectorAll("button")).find(e=>e.textContent==="Maybe later")?.click()');
await capture('after-mailbox');
await run('document.querySelector(".mail-message-select-row>input").focus()');await capture('after-keyboard-focus');
assert.equal(await run(`document.querySelector('.mail-message-select-row>input').getBoundingClientRect().right+5<=document.querySelector('.mail-sender').getBoundingClientRect().left`),true);
await run('document.querySelector(".mail-message-row").click()');
await until('!!document.querySelector(".mail-attachments")');
await capture('after-reader');
const reader=await run('document.querySelector("#mail-print-root .mail-message-header h2").textContent');
const started=performance.now();
for(let count=50;count<=250;count+=25){await run('Array.from(document.querySelectorAll(".mail-pagination button")).find(e=>e.textContent.includes("Load more")).click()');await until(`document.querySelectorAll('.mail-message-row').length===${count}`);}
assert.equal(await run('document.querySelector("#mail-print-root .mail-message-header h2").textContent'),reader);
await run('document.querySelector(".mail-message-scroll").scrollTop=document.querySelectorAll(".mail-message-select-row")[80].offsetTop');
const scroll=await run('document.querySelector(".mail-message-scroll").scrollTop');
await run('document.querySelectorAll(".mail-message-row")[80].dispatchEvent(new MouseEvent("click",{metaKey:true,bubbles:true}));document.querySelectorAll(".mail-message-row")[85].dispatchEvent(new MouseEvent("click",{metaKey:true,shiftKey:true,bubbles:true}))');
await until('document.querySelectorAll(".mail-message-select-row>input:checked").length===6');
assert.equal(await run('document.querySelector(".mail-message-scroll").scrollTop'),scroll);
assert.equal(await run(`Array.from(document.querySelectorAll('.mail-message-select-row')).every(row=>{const box=row.querySelector('input').getBoundingClientRect(),sender=row.querySelector('.mail-sender').getBoundingClientRect();return box.right+5<=sender.left;})`),true);
await capture('after-large-bulk');
await fetch('http://127.0.0.1:5483/fixture/arrival');await until('document.querySelector(".mail-pagination").textContent.includes("New mail available")');
assert.equal(await run('document.querySelectorAll(".mail-message-row").length'),250);assert.equal(await run('document.querySelector(".mail-message-scroll").scrollTop'),scroll);
await run('Array.from(document.querySelectorAll(".mail-pagination button")).find(e=>e.textContent.includes("Older messages")).click()');await until('document.querySelectorAll(".mail-message-row").length===25');
assert.equal(await run('document.querySelector("#mail-print-root .mail-message-header h2").textContent'),reader);
await run('Array.from(document.querySelectorAll(".mail-pagination button")).find(e=>e.textContent.includes("Back")).click()');await until('document.querySelectorAll(".mail-message-row").length===250');
assert.equal(await run('document.querySelector(".mail-message-scroll").scrollTop'),scroll);
const metrics=await run('({rows:document.querySelectorAll(".mail-message-row").length,nodes:document.querySelectorAll(".mail-message-list *").length,rowHeight:document.querySelector(".mail-message-row").getBoundingClientRect().height,scrollHeight:document.querySelector(".mail-message-scroll").scrollHeight})');
console.log(JSON.stringify({windowMs:Math.round(performance.now()-started),...metrics}));
console.log('FULL_SHELL_WINDOW_PASS');
const selector=label=>JSON.stringify(`[aria-label="${label}"]`);
await run(`document.querySelector(${selector('Newest messages')}).click()`);
await until('document.querySelectorAll(".mail-message-row").length===25');
await run('document.querySelector(".mail-message-row").click()');
await until('!!document.querySelector(".mail-attachments")');
await run(`document.querySelector(${selector('Add Agreement appendix.txt to chat')}).click()`);
await until(`!!document.querySelector(${selector('Attachment workspace')})`);
await run(`(()=>{const select=document.querySelector(${selector('Attachment workspace')});select.value="matter-aster";select.dispatchEvent(new Event("change",{bubbles:true}));})()`);
await until(`Array.from(document.querySelector(${selector('Attachment chat')}).options).some(e=>e.value==="ses_review")`);
await run(`(()=>{const select=document.querySelector(${selector('Attachment chat')});select.value="ses_review";select.dispatchEvent(new Event("change",{bubbles:true}));})()`);
await capture('after-attachment-chooser');
await run('Array.from(document.querySelectorAll("button")).find(e=>e.textContent==="Copy and add to draft").click()');
const sourceSelector=JSON.stringify('[contenteditable=true] [aria-label="Return to source email"]');
await until(`!!document.querySelector(${sourceSelector})`);
assert.equal(await run('document.querySelector("[contenteditable=true]").innerText.includes("source=%")'),false);
assert.equal(await run('document.querySelector("[contenteditable=true]").innerText.includes("Attachment from")'),false);
assert.equal(await run('document.querySelector("[contenteditable=true]").innerText.includes("Agreement appendix.txt")'),true);
await capture('after-chat-composer');
await run(`document.querySelector(${sourceSelector}).click()`);
await until('document.querySelector("#mail-print-root .mail-message-header h2")?.textContent==="Aster agreement · final comments"');
assert.equal(await run('document.querySelectorAll("[role=alert]").length'),0);
console.log('REAL_COMPOSER_SOURCE_PASS');
